import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{buildMedicine}from './medicine-meshes.js?v=20261023-physicscomplete01';import{medicineFigure}from './medicine-figures.js?v=20261023-physicscomplete01';
export function showMedicine(scene,w={}){let[kind,state]=scene.split(':'),names={memory:'Prepare a specific response',network:'Interrupt the contact network',treatment:'Relief and removal are different',susceptibility:'Match the effective antibiotic',host:'A difficult selective target',selection:'Selection changes a population',sources:'From a source to a candidate',preclinical:'Build evidence before human trials',screen:'Effectiveness is not the whole story',trial:'A fair comparison needs controls',dose:'Balance benefit and harm',results:'Compare the groups',review:'Scrutinise the evidence'},o={kind,state:state||'initial',revealed:true,...w},name=w.title||names[kind]||'Compare the evidence',figure=medicineFigure({...o,title:name});if(['screen','dose','results','review'].includes(kind)){renderDiagram(name,w.stateLabel||'Original illustrative evidence',figure,'MEDICINE EVIDENCE');return;}renderCustomModel({name,formula:w.stateLabel||'Inspect; compare the labelled diagram',kicker:'SCHEMATIC BIOLOGY MODEL',aria:name+'. Symbolic geometry; labelled diagram available.',atoms:[],bonds:[],radius:2.5,viewKey:'medicine-'+kind,startPaused:true,note:'Original model · symbolic scale and stages',diagram:figure,build:(g,T)=>buildMedicine(g,T,o)});}
